package com.nequard.community;
import com.nequard.auth.OrganizationAccessService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/community") public class CommunityController{private final CommunityNodeRepository repo;private final OrganizationAccessService access;public CommunityController(CommunityNodeRepository r,OrganizationAccessService a){repo=r;access=a;}@GetMapping("/nodes")public List<CommunityNode> nodes(Authentication a){return repo.findAll();}@PostMapping("/nodes")@PreAuthorize("hasAnyRole('SUPER_ADMIN','NETWORK_ADMIN','COMMUNITY_ADMIN')")public CommunityNode create(Authentication a,@RequestBody CommunityNode n){return repo.save(n);}}